mapper.select:
select
a.camera_id,
a.camera_name,
a.alias_name,
a.record_id,
a.up_region_id,
a.channel_num,
a.sms_id,
a.rms_id,
a.factory_name,
a.stream_type,
a.protocol_type,
a.url,
a.port,
a.camera_type,
a.is_control
from t_camera_info a
where 1 = 1
 and a.camera_id = #{cameraId, jdbcType=BIGINT}
 and a.camera_name = #{cameraName, jdbcType=VARCHAR}
 and a.alias_name = #{aliasName, jdbcType=VARCHAR}
 and a.record_id = #{recordId, jdbcType=VARCHAR}
 and a.up_region_id = #{upRegionId, jdbcType=BIGINT}
 and a.channel_num = #{channelNum, jdbcType=INTEGER}
 and a.sms_id = #{smsId, jdbcType=INTEGER}
 and a.rms_id = #{rmsId, jdbcType=INTEGER}
 and a.factory_name = #{factoryName, jdbcType=VARCHAR}
 and a.stream_type = #{streamType, jdbcType=INTEGER}
 and a.protocol_type = #{protocolType, jdbcType=INTEGER}
 and a.url = #{url, jdbcType=VARCHAR}
 and a.port = #{port, jdbcType=INTEGER}
 and a.camera_type = #{cameraType, jdbcType=INTEGER}
 and a.is_control = #{isControl, jdbcType=INTEGER}

